-- Fail the transaction if canonical counts, identities or paths drift.
DO $region_seed_assertions$
DECLARE
  actual_count integer;
BEGIN
  SELECT count(*)::integer
  INTO actual_count
  FROM "regions";

  IF actual_count <> 602 THEN
    RAISE EXCEPTION 'region seed total count mismatch: expected 602, got %', actual_count;
  END IF;

  SELECT count(*)::integer
  INTO actual_count
  FROM "regions"
  WHERE split_part("code", '-', 1) = 'CN' AND "level" = 'COUNTRY_REGION'::"region_level";

  IF actual_count <> 1 THEN
    RAISE EXCEPTION 'region seed CN/COUNTRY_REGION count mismatch: expected 1, got %', actual_count;
  END IF;

  SELECT count(*)::integer
  INTO actual_count
  FROM "regions"
  WHERE split_part("code", '-', 1) = 'CN' AND "level" = 'PROVINCE_STATE'::"region_level";

  IF actual_count <> 31 THEN
    RAISE EXCEPTION 'region seed CN/PROVINCE_STATE count mismatch: expected 31, got %', actual_count;
  END IF;

  SELECT count(*)::integer
  INTO actual_count
  FROM "regions"
  WHERE split_part("code", '-', 1) = 'CN' AND "level" = 'CITY'::"region_level";

  IF actual_count <> 369 THEN
    RAISE EXCEPTION 'region seed CN/CITY count mismatch: expected 369, got %', actual_count;
  END IF;

  SELECT count(*)::integer
  INTO actual_count
  FROM "regions"
  WHERE split_part("code", '-', 1) = 'TW' AND "level" = 'COUNTRY_REGION'::"region_level";

  IF actual_count <> 1 THEN
    RAISE EXCEPTION 'region seed TW/COUNTRY_REGION count mismatch: expected 1, got %', actual_count;
  END IF;

  SELECT count(*)::integer
  INTO actual_count
  FROM "regions"
  WHERE split_part("code", '-', 1) = 'TW' AND "level" = 'PROVINCE_STATE'::"region_level";

  IF actual_count <> 1 THEN
    RAISE EXCEPTION 'region seed TW/PROVINCE_STATE count mismatch: expected 1, got %', actual_count;
  END IF;

  SELECT count(*)::integer
  INTO actual_count
  FROM "regions"
  WHERE split_part("code", '-', 1) = 'TW' AND "level" = 'CITY'::"region_level";

  IF actual_count <> 22 THEN
    RAISE EXCEPTION 'region seed TW/CITY count mismatch: expected 22, got %', actual_count;
  END IF;

  SELECT count(*)::integer
  INTO actual_count
  FROM "regions"
  WHERE split_part("code", '-', 1) = 'MY' AND "level" = 'COUNTRY_REGION'::"region_level";

  IF actual_count <> 1 THEN
    RAISE EXCEPTION 'region seed MY/COUNTRY_REGION count mismatch: expected 1, got %', actual_count;
  END IF;

  SELECT count(*)::integer
  INTO actual_count
  FROM "regions"
  WHERE split_part("code", '-', 1) = 'MY' AND "level" = 'PROVINCE_STATE'::"region_level";

  IF actual_count <> 16 THEN
    RAISE EXCEPTION 'region seed MY/PROVINCE_STATE count mismatch: expected 16, got %', actual_count;
  END IF;

  SELECT count(*)::integer
  INTO actual_count
  FROM "regions"
  WHERE split_part("code", '-', 1) = 'MY' AND "level" = 'CITY'::"region_level";

  IF actual_count <> 160 THEN
    RAISE EXCEPTION 'region seed MY/CITY count mismatch: expected 160, got %', actual_count;
  END IF;

  SELECT count(DISTINCT "code")::integer
  INTO actual_count
  FROM "regions";

  IF actual_count <> 602 THEN
    RAISE EXCEPTION 'region seed unique code count mismatch: expected 602, got %', actual_count;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM "regions" AS city
    JOIN "regions" AS province ON province."id" = city."parent_id"
    JOIN "regions" AS country ON country."id" = province."parent_id"
    WHERE city."code" = 'CN-110000-CITY'
      AND city."name" = '北京市'
      AND city."source_code" = '110000'
      AND province."name" = '北京市'
      AND country."name" = '中国'
      AND city."level" = 'CITY'::"region_level"
      AND province."level" = 'PROVINCE_STATE'::"region_level"
      AND country."level" = 'COUNTRY_REGION'::"region_level"
  ) THEN
    RAISE EXCEPTION 'region seed path CN-110000-CITY mismatch';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM "regions" AS city
    JOIN "regions" AS province ON province."id" = city."parent_id"
    JOIN "regions" AS country ON country."id" = province."parent_id"
    WHERE city."code" = 'TW-64000'
      AND city."name" = '高雄市'
      AND city."source_code" = 'E/64000'
      AND province."name" = '台湾'
      AND country."name" = '中国台湾'
      AND city."level" = 'CITY'::"region_level"
      AND province."level" = 'PROVINCE_STATE'::"region_level"
      AND country."level" = 'COUNTRY_REGION'::"region_level"
  ) THEN
    RAISE EXCEPTION 'region seed path TW-64000 mismatch';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM "regions" AS city
    JOIN "regions" AS province ON province."id" = city."parent_id"
    JOIN "regions" AS country ON country."id" = province."parent_id"
    WHERE city."code" = 'MY-01-01'
      AND city."name" = 'Batu Pahat'
      AND city."source_code" = '1_1'
      AND province."name" = '柔佛'
      AND country."name" = '马来西亚'
      AND city."level" = 'CITY'::"region_level"
      AND province."level" = 'PROVINCE_STATE'::"region_level"
      AND country."level" = 'COUNTRY_REGION'::"region_level"
  ) THEN
    RAISE EXCEPTION 'region seed path MY-01-01 mismatch';
  END IF;
END;
$region_seed_assertions$;

COMMIT;
